pub fn fix_instructions(findings: &[ReviewFinding], ledger: &str) -> String {
    let mut s = String::from("Fix exactly these review findings, and nothing else:\n");
    for f in findings {
        s.push_str("- ");
        s.push_str(&f.line());
        s.push('\n');
    }
    s.push_str(&format!(
        "\nRecord a FIXED or WONTFIX line with your rationale for each finding in the review ledger at {ledger}, because the reviewer reads it on the next pass."
    ));
    s
}

match out.action {
    ResolveAction::Fix => {
        l.resolve_rounds += 1;
        l.open_before_resolve = Some(findings.len());
        // One verification pass per resolution round (review-cap.js).
        l.extra_cap += 1;
        let mut text = String::from(
            "Resolve these review findings with the instructions given for each:\n",
        );
        for i in &out.instructions {
            text.push_str(&format!(
                "- Finding: {}\n  Instruction: {}\n",
                i.finding, i.instruction
            ));
        }
        if out.instructions.is_empty() {
            text = fix_instructions(&findings, &ledger);
        } else {
            text.push_str(&format!("\nRecord a FIXED or WONTFIX line for each in the review ledger at {ledger}."));
        }
        l.next = LoopNext::Work {
            kind: WorkKind::Fix,
            instructions: Some(text),
        };
    }
    ResolveAction::Block => {
        l.next = LoopNext::Blocked {
            reason: format!(
                "The engine could not resolve the open review findings: {}. Ledger: {ledger}",
                out.reason
            ),
        };
    }
}

#[test]
fn review_loop_splits_autofix_fix_and_caps_at_three() {
    let mut h = H::plan_approved(&["p"], one_phase(), SessionOptions::default());
    h.run("spawn implementer", impl_submit(1, &["src/a.rs"]));
    // C1 is auto-fixable in this project; PHASE-REQ never is, whatever its Fix text.
    h.run(
        "spawn code-reviewer",
        review(&[
            finding("LOW", "C1"),
            finding("HIGH", "PHASE-REQ-1"),
            finding("LOW", "C9"),
        ]),
    );
    assert_eq!(h.summaries(), vec!["autofix phase 1"]);
    h.ev(SessionEvent::AutofixApplied {
        project: "p".into(),
        phase: 1,
        tests: false,
        applied: vec!["x".into()],
        failed: vec![],
    });
    let fix = h.spawn_step("spawn implementer phase 1 fix");
    let text = fix.inputs.instructions.unwrap();
    assert!(
        text.contains("PHASE-REQ-1") && !text.contains("C9"),
        "only HIGH and MEDIUM go to the fix agent"
    );

